var GHSS_Helper = Class.create();
GHSS_Helper.prototype = {
    initialize: function() {
        var env = gs.getProperty('x_hsb11_mss_c_ghss.mss_ghss_base_endpoint');
        var token = gs.getProperty('x_hsb11_mss_c_ghss.api_token');


        this.env = env;
        this.token = token;
    },

    //This  function is to call outbound rest message for Confirm Trade method
    confirm_fun: function(maker, checker, reference, lastUpdDate, generateAdvice, outboundId) {
        //MSSCUSTODY-5374 - Added error handling as part of this JIRA
        try {
            var sr = new sn_ws.RESTMessageV2("GHSS Outbound Api", "Confirm Trade");
            sr.setStringParameterNoEscape("ghss_api_token", this.token);
            sr.setStringParameterNoEscape("base_ghss_endpoint", this.env);
            sr.setStringParameterNoEscape("confirm_trade_endpoint", gs.getProperty('x_hsb11_mss_c_ghss.ghss_confirm_method'));
            sr.setStringParameterNoEscape("maker", maker);
            sr.setStringParameterNoEscape("checker", checker);
            sr.setStringParameterNoEscape("reference", reference);
            sr.setStringParameterNoEscape("lastUpdDate", lastUpdDate);
            //Logic modified as part of MSSCUSTODY-4090.GenerateAdvice to be sent as False only when advice = Client Preference. Else it will sent as empty.
            if (generateAdvice == false) {
                sr.setStringParameterNoEscape("generateAdvice", generateAdvice);
            } else if (generateAdvice == true) {
                sr.setStringParameterNoEscape("generateAdvice", null);
            }
            sr.setEccCorrelator(outboundId);
            sr.executeAsync();
        }
        //MSSCUSTODY-5374
        catch (e) {
            gs.error("[GHSS Helper] Error :" + e.message); //MSSCUSTODY-5374
        }
    },

    //This function is to call outbound rest message for Resume Trade method
    resume_fun: function(maker, checker, reference, lastUpdDate, generateAdvice, suspenseTradeStatus, remark, reasonCode, outboundId) {
        //MSSCUSTODY-5374 - Added error handling as part of this JIRA
        try {
            var sr = new sn_ws.RESTMessageV2("GHSS Outbound Api", "Resume Trade");
            sr.setStringParameterNoEscape("ghss_api_token", this.token);
            sr.setStringParameterNoEscape("base_ghss_endpoint", this.env);
            sr.setStringParameterNoEscape("resume_trade_endpoint", gs.getProperty('x_hsb11_mss_c_ghss.ghss_resume_method'));
            sr.setStringParameterNoEscape("maker", maker);
            sr.setStringParameterNoEscape("checker", checker);
            sr.setStringParameterNoEscape("reference", reference);
            sr.setStringParameterNoEscape("lastUpdateDate", lastUpdDate);
            //sr.setStringParameterNoEscape("generateAdvice", generateAdvice);
            //MSSCUSTODY-4874 -- Addtional logic for resume also, after the changes implemented as part of MSSCUSTODY-4090
            if (generateAdvice == false) {
                sr.setStringParameterNoEscape("generateAdvice", generateAdvice);
            } else if (generateAdvice == true) {
                sr.setStringParameterNoEscape("generateAdvice", null);
            }
            //---MSSCUSTODY-4874--

            sr.setStringParameterNoEscape("suspenseTradeStatus", suspenseTradeStatus);
            sr.setStringParameterNoEscape("remark", remark);
            sr.setStringParameterNoEscape("reasonCode", reasonCode);
            sr.setEccCorrelator(outboundId);
            sr.executeAsync();
        }
        //MSSCUSTODY-5374
        catch (e) {
            gs.error("[GHSS Helper] Error :" + e.message); //MSSCUSTODY-5374
        }
    },

