    //MSSCUSTODY-6087: Added  function for cancel widget for GC HK
    // This function is to call outbound REST message for Cancel Trade method
    cancel_fun_gc: function(maker, checker, reference, lastUpdDate, generateAdvice, reasonCode, cancelReferenceIdentifier, cancelledByIndicator, fxCxIndicator, collectChargeIndicator, gdiIndicator, remarkText, outboundId) {
        try {
            var sr = new sn_ws.RESTMessageV2("GHSS Outbound Api", "Cancel Trade GC");
            sr.setStringParameterNoEscape("ghss_api_token", this.token);
            sr.setStringParameterNoEscape("base_ghss_endpoint", this.env);
            sr.setStringParameterNoEscape("cancel_trade_endpoint", gs.getProperty('x_hsb11_mss_c_ghss.ghss_cancel_method'));
            sr.setStringParameterNoEscape("maker", maker);
            sr.setStringParameterNoEscape("checker", checker);
            sr.setStringParameterNoEscape("reference", reference);
            sr.setStringParameterNoEscape("lastUpdDate", lastUpdDate);

            // Logic for generateAdviceIndicator
            if (generateAdvice == false) {
                sr.setStringParameterNoEscape("generateAdvice", generateAdvice);
            } else if (generateAdvice == true) {
                sr.setStringParameterNoEscape("generateAdvice", null);
            }

			//Logic for generateAdviceIndicator
			if(!fxCxIndicator){
				sr.setStringParameterNoEscape("fxCxIndicator", null);
			}else{
				sr.setStringParameterNoEscape("fxCxIndicator", '"' + fxCxIndicator + '"');
			}

			gs.info("6087: GDI" + gdiIndicator);
			if(gdiIndicator == "null"){
				sr.setStringParameterNoEscape("gdiIndicator", null);
			}else if(gdiIndicator == "N"){
				sr.setStringParameterNoEscape("gdiIndicator", '"' + gdiIndicator + '"');
			}

            sr.setStringParameterNoEscape("reasonCode", reasonCode);
            sr.setStringParameterNoEscape("cancelReferenceIdentifier", cancelReferenceIdentifier);
            sr.setStringParameterNoEscape("cancelledByIndicator", cancelledByIndicator);
            sr.setStringParameterNoEscape("collectCharge", collectChargeIndicator);
            //sr.setStringParameterNoEscape("fxCxIndicator", fxCxIndicator);
            //sr.setStringParameterNoEscape("gdiIndicator", gdiIndicator);
			sr.setStringParameterNoEscape("remark", remarkText);
            sr.setEccCorrelator(outboundId);
            sr.executeAsync();
        } catch (e) {
            gs.error("[GHSS Helper] Error :" + e.message);
        }
    },

