    //This function is to update the task state based on response
    updateTaskRecord: function(sn_task, state, retryCount, responseCode, responseBody) {
        var taskRecord = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
        var retry_cnt = gs.getProperty("x_hsb11_mss_c_ghss.ghss_retry_count");
        taskRecord.addQuery("sys_id", sn_task);
        taskRecord.addActiveQuery();
        taskRecord.query();
        if (taskRecord.next()) {
            if (state == "processed_ghss") {
                var bulk_id = taskRecord.bulk_id;
                //MSSCUSTODY-4282 - Updating active trade count in bulk form 
                // Try to decrement the active_trade_count for BULK
                try {
                    // new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().decrementTradeCount(bulk_id);
                } catch (e) {

                }
                //MSSCUSTODY-4282 - decrement for the active_trade_count field
                taskRecord.state = 3; // Closed Complete
                taskRecord.outcome = "Automated Task Completed - Request Success";
            } else if (state == "error_ghss") {

                // if response code is 200 and 400 then directly update state, for other code check retry count 	
                if ((responseCode == "200" || responseCode == "400") || retryCount == retry_cnt) {
                    taskRecord.state = 4; // Closed Rejected
                    taskRecord.outcome = "Automated Task Incomplete - Create manual task";
                    //taskRecord.sub_trade_task_type = "Automation Failed"; //Added as part of MSSCUSTODY-3745 to map sub trade task type when automation is failing
                    taskRecord.work_notes = "Recieved error from Widget : " + responseBody.toString(); // MSSCUSTODY-4148 - Removed GHSS word from work note to make it generic
                }
            }
        }
        taskRecord.update();
    },

    //This function is for initializing the outbound table when scripted Rest API is called.
    ghssScriptedUpdateOutbound: function(requestBody) {
        // This code has been writtenf for Story-192 and commented out since it is yet to be decided
        // This code has been reviewed again as part of MSSOTIQUBE-1199
        var curdate = new GlideDateTime();
        var outbound = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
        var parsed = new global.JSON.parse(requestBody); // new line for 192
        outbound.initialize();
        outbound.request_body = requestBody;
        outbound.request_type = parsed["request_type"];
        outbound.sn_task = parsed["servicenowid"];
        outbound.state = "ready_ghss"; // direct,not taken from request body
        outbound.maker = parsed["maker"];
        outbound.checker = parsed["checker"];
        outbound.reference = parsed["reference"];
        outbound.last_update_date_time = parsed["last_update_date_time"];
        outbound.generate_advice = parsed["generate_advice"];
        outbound.suspense_trade_status = parsed["suspense_trade_status"];
        outbound.remark = parsed["remark"];
        outbound.reason_code = parsed["reason_code"];
        outbound.request_date = curdate;
        outbound.settle_indicator = parsed["settle_indicator"];
        outbound.auto_resume_indicator = parsed["auto_resume_indicator"];
        outbound.cancel_code = parsed["cancellation_reason_code"];
        outbound.cancelled_by_indicator = parsed["cancelled_by_indicator"];
        outbound.collect_charge_indicator = parsed["collect_cancel_charge"];
        outbound.cancel_reference = parsed["cancellation_reference"];
        outbound.fxr_td = parsed["cancel_fx_indicator"];
        outbound.value_date = parsed["value_date"];
        outbound.settlement_date = parsed["settlement_date"];
		outbound.fx_cx = parsed["fx_cx"];
		outbound.gdi_indicator = parsed["gdi_indicator"];
        outbound.insert();


        // var curdate = new GlideDateTime();
        // var outbound = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
