        // outbound.reference = requestBody.reference;
        // outbound.last_update_date_time = requestBody.last_update_date_time;
        // outbound.generate_advice = requestBody.generate_advice;
        // outbound.suspense_trade_status = requestBody.suspense_trade_status;
